/**
 * `pnpm check:tokens-only`: hand-written CSS consumes tokens, never raw values or brand names.
 * Guard rules only, no formatting opinions. The token rules themselves are in CLAUDE.md.
 *
 * Not linted:
 *   src/styles/tokens.css  generated by Terrazzo; the one place primitives and [data-brand] live
 *   src/styles/reset.css   brand-agnostic normalization (0, 100%, 100vh, reduced-motion overrides)
 *   src/styles/fonts.css   @font-face rules: font names, file URLs, metric overrides. Faces reach components only via --type-family-*
 *
 * Escape hatch: `stylelint-disable-next-line <rule> -- <reason>`. A disable without a reason fails.
 */
const varOnly = { values: ['/^var\\(--[\\w-]+\\)$/', 'inherit'], message: 'must be a single var(--…) token' };

/** @type {import('stylelint').Config} */
export default {
  plugins: ['./scripts/stylelint-plugin-tokens.ts'],
  ignoreFiles: ['src/styles/tokens.css', 'src/styles/reset.css', 'src/styles/fonts.css'],
  reportDescriptionlessDisables: true,
  reportNeedlessDisables: true,
  reportInvalidScopeDisables: true,
  rules: {
    // Only semantic and component tokens (or private --_ props), and nothing keyed on a brand.
    'tokens/tier-vars': true,
    'tokens/no-brand-keys': true,

    // Raw colors.
    'color-no-hex': [true, { message: 'Raw hex color. Use a semantic or component color token.' }],
    'color-named': ['never', { message: 'Named color. Use a semantic or component color token.' }],
    'function-disallowed-list': [
      ['rgb', 'rgba', 'hsl', 'hsla', 'hwb', 'lab', 'lch', 'oklab', 'oklch', 'color', 'color-mix', 'light-dark'],
      { message: (fn) => `Color function ${fn}() is a raw color (and escapes check:contrast). Use a token.` },
    ],

    // Raw lengths and durations: any unit except % and fr. Unitless 0 is always allowed. Durations come from --motion-*.
    'unit-allowed-list': [['%', 'fr'], { message: (unit) => `Raw "${unit}" value. Use a --space-*, --shape-* or component token.` }],

    // Typography comes from --type-* or component tokens, whole.
    'declaration-property-value-allowed-list': [
      {
        font: varOnly.values,
        'font-family': varOnly.values,
        'font-size': varOnly.values,
        'font-weight': varOnly.values,
        'line-height': varOnly.values,
        'letter-spacing': varOnly.values,
        'font-variation-settings': varOnly.values,
      },
      { message: (prop, value) => `${prop}: ${value} ${varOnly.message} (a --type-* or component token).` },
    ],
  },
};
